def count_divisors(n):
    count = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2
        i += 1
    return count

def find_nth_multiple_of_4_divisors(n):
    count = 0
    n_count = 0
    while True:
        n_count += 1
        if count_divisors(n_count) % 4 == 0:
            count = n_count
            if n_count == n:
                return n_count
